import {Button, SegmentedControl} from '@primer/react'
import {useEffect, useRef, useState} from 'react'

import {useFileSyncerContext} from '../../../contexts/FileSyncerContext'
import {useTargetedEditsContext} from '../../../contexts/TargetedEditsContext'
import {ReadOnlyKey, useReadOnly} from '../../../hooks/use-read-only'
import {
  BorderRadiusFullIcon,
  BorderRadiusLargeIcon,
  BorderRadiusMediumIcon,
  BorderRadiusNoneIcon,
  BorderRadiusSmallIcon,
  SpacingLargeIcon,
  SpacingMediumIcon,
  SpacingSmallIcon,
} from '../../CustomIcons'
import {ColorPickerItem} from '../ColorPickerItem'
import {FontPickerItem} from '../FontPickerItem'
import {Overscroll} from '../Overscroll'
import {Section} from '../Section'
import {ThemePresetPicker} from '../ThemePresetPicker'
import {fonts} from '../utils/fonts'
import type {ThemePreset} from '../utils/presets'

const CSS_FILE_PATH = 'src/index.css'

export function ThemePanel() {
  const {modifyGlobalCssVariable, modifyThemeVariables, modifyFontFamily, themeVariables, refetchThemeVariables} =
    useTargetedEditsContext()

  const {fileChangeStack} = useFileSyncerContext()

  const readOnly = useReadOnly(ReadOnlyKey.THEME_PANEL)

  const scrollRef = useRef<HTMLDivElement>(null)
  const [showAllColors, setShowAllColors] = useState(false)

  useEffect(() => {
    refetchThemeVariables()
  }, [refetchThemeVariables])

  useEffect(() => {
    for (const change of fileChangeStack) {
      if (change.path === CSS_FILE_PATH) {
        refetchThemeVariables()
      }
    }
  }, [fileChangeStack, refetchThemeVariables])

  if (!themeVariables) {
    return null
  }

  const handleThemeChange = async (newTheme: ThemePreset) => {
    const {'font-mono': mono, 'font-sans': sans, 'font-serif': serif, ...variables} = newTheme.styles.light

    await Promise.allSettled([
      modifyFontFamily({
        sans: sans ?? themeVariables['font-sans'],
        serif: serif ?? themeVariables['font-serif'],
        mono: mono ?? themeVariables['font-mono'],
      }),
      modifyThemeVariables({
        updates: Object.entries(variables).map(([key, value]) => ({
          name: key,
          value,
        })),
      }),
    ])
  }

  const handleFontChange = (fontType: 'sans' | 'serif' | 'mono', font: string) => {
    // we need to always send all fonts so we correctly build the google font link
    modifyFontFamily({
      sans: fontType === 'sans' ? font : themeVariables['font-sans'],
      serif: fontType === 'serif' ? font : themeVariables['font-serif'],
      mono: fontType === 'mono' ? font : themeVariables['font-mono'],
    })
  }

  return (
    <div className="position-relative mt-3">
      <Overscroll scrollingRef={scrollRef} />
      <div ref={scrollRef} style={{margin: 'calc(var(--base-size-16, 16px) * -1)'}}>
        <Section title="Theme presets" variant="bordered" showTitle={false} readOnly={readOnly}>
          <ThemePresetPicker onChange={handleThemeChange} themeVariables={themeVariables} />
        </Section>
        <Section title="Typography" variant="bordered" readOnly={readOnly}>
          <Section.Group label="Sans serif" columns={1}>
            <FontPickerItem
              label="Sans-serif"
              value={themeVariables['font-sans']}
              onChange={font => handleFontChange('sans', font)}
              items={fonts.sans}
            />
          </Section.Group>
          <Section.Group label="Serif" columns={1}>
            <FontPickerItem
              label="Serif"
              value={themeVariables['font-serif']}
              onChange={font => handleFontChange('serif', font)}
              items={fonts.serif}
            />
          </Section.Group>
          <Section.Group label="Monospace" columns={1}>
            <FontPickerItem
              label="Monospace"
              value={themeVariables['font-mono']}
              onChange={font => handleFontChange('mono', font)}
              items={fonts.mono}
            />
          </Section.Group>
        </Section>
        <Section title="Color" variant="bordered" readOnly={readOnly}>
          <Section.GroupLabels label1="Background" label2="Text" />
          <Section.Group label="Accent">
            <ColorPickerItem
              label="Background"
              value={themeVariables['accent']}
              onChange={color => modifyGlobalCssVariable({name: 'accent', value: color.value})}
            />
            <ColorPickerItem
              label="Text"
              value={themeVariables['accent-foreground']}
              onChange={color => modifyGlobalCssVariable({name: 'accent-foreground', value: color.value})}
            />
          </Section.Group>
          <Section.Group label="Primary">
            <ColorPickerItem
              label="Background"
              value={themeVariables['primary']}
              onChange={color => modifyGlobalCssVariable({name: 'primary', value: color.value})}
            />
            <ColorPickerItem
              label="Text"
              value={themeVariables['primary-foreground']}
              onChange={color => modifyGlobalCssVariable({name: 'primary-foreground', value: color.value})}
            />
          </Section.Group>
          <Section.Group label="Secondary">
            <ColorPickerItem
              label="Background"
              value={themeVariables['secondary']}
              onChange={color => modifyGlobalCssVariable({name: 'secondary', value: color.value})}
            />
            <ColorPickerItem
              label="Text"
              value={themeVariables['secondary-foreground']}
              onChange={color => modifyGlobalCssVariable({name: 'secondary-foreground', value: color.value})}
            />
          </Section.Group>
          <Section.Group label="Base">
            <ColorPickerItem
              label="Background"
              value={themeVariables['background']}
              onChange={color => modifyGlobalCssVariable({name: 'background', value: color.value})}
            />
            <ColorPickerItem
              label="Text"
              value={themeVariables['foreground']}
              onChange={color => modifyGlobalCssVariable({name: 'foreground', value: color.value})}
            />
          </Section.Group>
          {showAllColors && (
            <>
              <Section.Group label="Muted">
                <ColorPickerItem
                  label="Background"
                  value={themeVariables['muted']}
                  onChange={color => modifyGlobalCssVariable({name: 'muted', value: color.value})}
                />
                <ColorPickerItem
                  label="Text"
                  value={themeVariables['muted-foreground']}
                  onChange={color => modifyGlobalCssVariable({name: 'muted-foreground', value: color.value})}
                />
              </Section.Group>
              <Section.Group label="Destructive">
                <ColorPickerItem
                  label="Background"
                  value={themeVariables['destructive']}
                  onChange={color => modifyGlobalCssVariable({name: 'destructive', value: color.value})}
                />
                <ColorPickerItem
                  label="Text"
                  value={themeVariables['destructive-foreground']}
                  onChange={color => modifyGlobalCssVariable({name: 'destructive-foreground', value: color.value})}
                />
              </Section.Group>
              <Section.Group label="Card">
                <ColorPickerItem
                  label="Background"
                  value={themeVariables['card']}
                  onChange={color => modifyGlobalCssVariable({name: 'card', value: color.value})}
                />
                <ColorPickerItem
                  label="Text"
                  value={themeVariables['card-foreground']}
                  onChange={color => modifyGlobalCssVariable({name: 'card-foreground', value: color.value})}
                />
              </Section.Group>
              <Section.Group label="Popover">
                <ColorPickerItem
                  label="Background"
                  value={themeVariables['popover']}
                  onChange={color => modifyGlobalCssVariable({name: 'popover', value: color.value})}
                />
                <ColorPickerItem
                  label="Text"
                  value={themeVariables['popover-foreground']}
                  onChange={color => modifyGlobalCssVariable({name: 'popover-foreground', value: color.value})}
                />
              </Section.Group>
              <Section.Group label="Input">
                <ColorPickerItem
                  label="Background"
                  value={themeVariables['input']}
                  onChange={color => modifyGlobalCssVariable({name: 'input', value: color.value})}
                />
              </Section.Group>
              <Section.Group label="Border">
                <ColorPickerItem
                  label="Background"
                  value={themeVariables['border']}
                  onChange={color => modifyGlobalCssVariable({name: 'border', value: color.value})}
                />
              </Section.Group>
              <Section.Group label="Ring">
                <ColorPickerItem
                  label="Background"
                  value={themeVariables['ring']}
                  onChange={color => modifyGlobalCssVariable({name: 'ring', value: color.value})}
                />
              </Section.Group>
            </>
          )}
          <div className="pt-2">
            <Button block size="small" onClick={() => setShowAllColors(s => !s)}>
              {showAllColors ? 'Hide colors' : 'Show all colors'}
            </Button>
          </div>
        </Section>

        <Section title="Appearance" variant="bordered">
          <Section.Group label="Border radius" columns={1}>
            <div>
              <SegmentedControl aria-label="Border radius" size="small" className="fgColor-muted">
                <SegmentedControl.IconButton
                  disabled={readOnly}
                  aria-label="None"
                  icon={<BorderRadiusNoneIcon className="octicon" />}
                  selected={themeVariables['radius'] === '0rem'}
                  onClick={() => {
                    modifyGlobalCssVariable({name: 'radius', value: '0rem'})
                  }}
                />
                <SegmentedControl.IconButton
                  disabled={readOnly}
                  aria-label="Small"
                  icon={<BorderRadiusSmallIcon className="octicon" />}
                  selected={themeVariables['radius'] === '0.25rem'}
                  onClick={() => {
                    modifyGlobalCssVariable({name: 'radius', value: '0.25rem'})
                  }}
                />
                <SegmentedControl.IconButton
                  disabled={readOnly}
                  aria-label="Medium"
                  icon={<BorderRadiusMediumIcon className="octicon" />}
                  selected={themeVariables['radius'] === '0.5rem'}
                  onClick={() => {
                    modifyGlobalCssVariable({name: 'radius', value: '0.5rem'})
                  }}
                />
                <SegmentedControl.IconButton
                  disabled={readOnly}
                  aria-label="Large"
                  icon={<BorderRadiusLargeIcon className="octicon" />}
                  selected={themeVariables['radius'] === '0.75rem'}
                  onClick={() => {
                    modifyGlobalCssVariable({name: 'radius', value: '0.75rem'})
                  }}
                />
                <SegmentedControl.IconButton
                  disabled={readOnly}
                  aria-label="Full"
                  icon={<BorderRadiusFullIcon className="octicon" />}
                  selected={themeVariables['radius'] === '1rem'}
                  onClick={() => {
                    modifyGlobalCssVariable({name: 'radius', value: '1rem'})
                  }}
                />
              </SegmentedControl>
            </div>
          </Section.Group>
          <Section.Group label="Spacing" columns={1}>
            <div>
              <SegmentedControl aria-label="Spacing" size="small" className="fgColor-muted">
                <SegmentedControl.IconButton
                  disabled={readOnly}
                  aria-label="None"
                  icon={<SpacingSmallIcon className="octicon" />}
                  selected={themeVariables['spacing'] === '0.20rem'}
                  onClick={() => {
                    modifyGlobalCssVariable({name: 'spacing', value: '0.20rem'})
                  }}
                />
                <SegmentedControl.IconButton
                  disabled={readOnly}
                  aria-label="Small"
                  icon={<SpacingMediumIcon className="octicon" />}
                  selected={themeVariables['spacing'] === '0.25rem'}
                  onClick={() => {
                    modifyGlobalCssVariable({name: 'spacing', value: '0.25rem'})
                  }}
                />
                <SegmentedControl.IconButton
                  disabled={readOnly}
                  aria-label="Medium"
                  icon={<SpacingLargeIcon className="octicon" />}
                  selected={themeVariables['spacing'] === '0.3rem'}
                  onClick={() => {
                    modifyGlobalCssVariable({name: 'spacing', value: '0.3rem'})
                  }}
                />
              </SegmentedControl>
            </div>
          </Section.Group>
        </Section>
      </div>
    </div>
  )
}

try{ ThemePanel.displayName ||= 'ThemePanel' } catch {}